$:set -euo pipefail
if test -f README.md; then cat README.md >/dev/null; fi
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'
"use strict";
const fs=require("fs"),assert=require("assert"),crypto=require("crypto");
const p={
draft:"Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json",
copy:"Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json",
scope:"references/user-defined-scope-rule.json",
lookup:"references/instruction-wrapper-key-aliases.json",
task:"Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json"
};
const read=n=>JSON.parse(fs.readFileSync(p[n],"utf8"));
const write=(n,v,compact=false)=>fs.writeFileSync(p[n],JSON.stringify(v,null,compact?0:2)+"\n");
const draft=read("draft"),scope=read("scope"),existingCopy=read("copy"),mapping=read("lookup"),task=read("task");
assert(Array.isArray(draft)&&draft.length===3);
assert.deepStrictEqual(draft[1],scope);
assert(scope.title==="User-Defined Operational Scope" && scope.examples.length===10);
assert(task.status==="pending_revision");
assert(existingCopy[0].alias_lookup_path===p.lookup);
const revised=structuredClone(draft);
revised[1]={title:scope.title,applicability:scope.applicability,standalone_rule_path:p.scope};
const originalAliasByName=new Map(Object.entries(mapping.alias_to_key).map(([alias,key])=>[key,alias]));
const requiredKeys=new Set();
function visit(v){
 if(Array.isArray(v)){for(const i of v)visit(i);return;}
 if(v===null||typeof v!=="object")return;
 for(const [k,n]of Object.entries(v)){requiredKeys.add(k);visit(n);}
}
visit(revised);
const aliasToKey={};
for(const k of requiredKeys) {
 const alias=originalAliasByName.get(k);
 assert(typeof alias==="string"&&alias[0]===k[0]&&alias.length<=2,"Key alias missing: "+k);
 aliasToKey[alias]=k;
}
assert(Object.keys(aliasToKey).length===requiredKeys.size);
const keyToAlias=new Map(Object.entries(aliasToKey).map(([a,k])=>[k,a]));
function encode(v) {
 if(Array.isArray(v))return v.map(encode);
 if(v===null||typeof v!=="object")return v;
 const out={};for(const [k,n]of Object.entries(v)){out[keyToAlias.get(k)]=encode(n);}return out;
}
function decode(v){
 if(Array.isArray(v))return v.map(decode);
 if(v===null||typeof v!=="object")return v;
 const out={};for(const [k,n]of Object.entries(v)){
  const original=k==="alias_lookup_path"?k:aliasToKey[k];
  assert(original,"Unknown alias "+k);
  out[original]=decode(n);
 }return out;
}
const copy=encode(revised);
copy[0].alias_lookup_path=p.lookup;
const checked=decode(copy);delete checked[0].alias_lookup_path;
assert.deepStrictEqual(checked,revised);
assert.deepStrictEqual(revised[0],draft[0]);
assert.deepStrictEqual(revised[2],draft[2]);
mapping.alias_to_key=aliasToKey;
mapping.original_key_count=requiredKeys.size;
mapping.total_key_count_including_lookup=requiredKeys.size;
mapping.aliases_with_one_character=Object.keys(aliasToKey).filter(k=>k.length===1).length;
mapping.aliases_with_two_characters=Object.keys(aliasToKey).filter(k=>k.length===2).length;
mapping.source_template_sha256=crypto.createHash("sha256").update(JSON.stringify(revised,null,2)+"\n").digest("hex");
task.task.amendments.push({
 purpose:"Shorten outer index-one scope instruction without changing the complete standalone rule.",
 user_instruction_summary:"Keep title and applicability; remove all other members from the embedded rule and add a path to the standalone scope reference.",
 implementation:"Outer index 1 now contains title, applicability, and standalone_rule_path only. The complete model and ten examples remain in references/user-defined-scope-rule.json. The aliased copy and lookup are synchronized.",
 status:"pending_user_review"
});
task.task.deliverable="Wrapper draft with title, applicability and standalone_rule_path for User-Defined Scope, and analogous referenced Conversation Analytics rule, plus external rule standards and equivalent aliased copy.";
write("draft",revised);
write("copy",copy,true);
write("lookup",mapping);
write("task",task);
const verified=decode(read("copy"));delete verified[0].alias_lookup_path;
assert.deepStrictEqual(verified,read("draft"));
assert.deepStrictEqual(read("scope"),scope);
assert(read("task").status==="pending_revision");
assert.deepStrictEqual(Object.keys(read("draft")[1]),["title","applicability","standalone_rule_path"]);
console.log("SCOPE_DESCRIPTOR",JSON.stringify(revised[1]));
console.log("REFERENCE_PRESERVED",scope.examples.length);
console.log("ALIAS_ROUNDTRIP_VALID",true);
console.log("ALIAS_COUNT",requiredKeys.size);
console.log("DRAFT_CHARS",fs.readFileSync(p.draft,"utf8").length);
console.log("ALIAS_CHARS",fs.readFileSync(p.copy,"utf8").length);

NODE
git add -- 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json' 'references/instruction-wrapper-key-aliases.json'
git diff --cached --check
git commit -m 'Abbreviate scope instruction in template and retain external full reference'
for i in 1 2 3 4; do git fetch origin main -q; git rebase origin/main -q; if git push origin HEAD:main; then break; fi; test "$i" -lt 4; done
printf 'PUBLISHED_COMMIT ';git rev-parse HEAD
git show --stat --oneline HEAD
